# ====================================================== OAD-13 clase 5
F = ("Ficha 5 (de ejemplo). Conteo de residuos de una limpieza voluntaria en una orilla de río, 60 residuos en total: envases de plástico 24, papel y cartón 10, "
     "latas 8, botellas de vidrio 6, otros 12. Se quiere mostrar los datos en una tabla y en un gráfico de barras.")
